        if (accountRequests != null) {

            for (Object o : accountRequests) {

                AccountRequest acctReq = (AccountRequest) o;
                AccountRequest.Operation op = acctReq.getOperation();

                if (op == null) {
                    log.warn("AccountRequest with null operation encountered, skipping.");
                    continue;
                }

                // Resolve the Identity behind this native identity so we can
                // derive username/firstname/lastname/email consistently.
                // plan.getIdentity() can return either a String (identity name)
                // or an Identity object depending on how the plan was built, so
                // handle both cases instead of assuming String.
                String nativeIdentity = acctReq.getNativeIdentity();
                Object planIdentityObj = plan.getIdentity();

                String identityName = null;
                Identity idn = null;

                if (planIdentityObj instanceof Identity) {
                    idn = (Identity) planIdentityObj;
                    identityName = idn.getName();
                } else if (planIdentityObj instanceof String) {
                    identityName = (String) planIdentityObj;
                }

                if (identityName == null) {
                    identityName = nativeIdentity;
                }

                if (idn == null && identityName != null) {
                    idn = context.getObjectByName(Identity.class, identityName);
                }

                String fullName = (idn != null) ? idn.getDisplayName() : identityName;
                if (fullName == null) {
                    fullName = identityName;
                }

                // Prefer the Identity's own firstname/lastname attributes
                // (populated from your authoritative source) over splitting
                // the display name, since display names aren't reliably
                // "First Last" (e.g. single-word names, middle names, etc.)
                String firstname = null;
                String lastname = null;

                if (idn != null) {
                    firstname = safeGetString(idn.getAttribute("firstname"));
                    lastname = safeGetString(idn.getAttribute("lastname"));
                }

                if (firstname == null || lastname == null) {
                    String[] nameParts = splitName(fullName);
                    if (firstname == null) firstname = nameParts[0];
                    if (lastname == null) lastname = nameParts[1];
                }

                // employee_id = identity's username attribute, falling back to
                // the identity's name, then to the native identity, in case the
                // "username" attribute isn't populated on this identity (common
                // on Create requests where nativeIdentity is also not yet set).
                String employeeId = null;
                if (idn != null) {
                    employeeId = safeGetString(idn.getAttribute("username"));
                }
                if (employeeId == null) {
                    employeeId = safeGetString(identityName);
                }
                if (employeeId == null) {
                    employeeId = safeGetString(nativeIdentity);
                }

                if (employeeId == null) {
                    log.error("Unable to resolve employee_id for this AccountRequest (username attribute, identityName, and nativeIdentity were all null). Skipping this request.");
                    result.setStatus(ProvisioningResult.STATUS_FAILED);
                    result.addError("Unable to resolve employee_id: username, identityName, and nativeIdentity were all null.");
                    continue;
                }

                String username = fullName;
                String email = (firstname + "." + lastname + "@msql.com").toLowerCase();

                PreparedStatement statement = null;

                try {

                    if (AccountRequest.Operation.Create.equals(op)) {

                        // Department comes from the selected entitlement/access
                        // on the account request (e.g. "security"), if present.
                        String department = getAttrValue(acctReq, DEPARTMENT_ATTR);

                        statement = connection.prepareStatement(
                            "INSERT INTO employee (employee_id, username, firstname, lastname, email, department, status) " +
                            "VALUES (?,?,?,?,?,?,?) " +
                            "ON DUPLICATE KEY UPDATE username=VALUES(username), firstname=VALUES(firstname), " +
                            "lastname=VALUES(lastname), email=VALUES(email), department=VALUES(department), status=VALUES(status)"
                        );
                        statement.setString(1, employeeId);
                        statement.setString(2, username);
                        statement.setString(3, firstname);
                        statement.setString(4, lastname);
                        statement.setString(5, email);
                        statement.setString(6, department);
                        statement.setInt(7, 1); // status = active on create
                        statement.executeUpdate();

                        log.info("Created/updated employee row for employee_id: " + employeeId);
                        result.setStatus(ProvisioningResult.STATUS_COMMITTED);

                    } else if (AccountRequest.Operation.Modify.equals(op)) {

                        java.util.List attributeRequests = acctReq.getAttributeRequests();

                        if (attributeRequests != null) {
                            for (Object ao : attributeRequests) {
                                AttributeRequest attrReq = (AttributeRequest) ao;

                                if (!DEPARTMENT_ATTR.equals(attrReq.getName())) {
                                    continue; // only handling department/access changes here
                                }

                                if (ProvisioningPlan.Operation.Add.equals(attrReq.getOperation())) {

                                    String newDept = safeGetString(attrReq.getValue());
                                    statement = connection.prepareStatement(
                                        "UPDATE employee SET department = ? WHERE employee_id = ?"
                                    );
                                    statement.setString(1, newDept);
