                                    statement = connection.prepareStatement(
                                        "UPDATE employee SET department = NULL WHERE employee_id = ?"
                                    );
                                    statement.setString(1, employeeId);
                                    statement.executeUpdate();
                                    log.info("Removed department for employee_id: " + employeeId);

                                } else if (ProvisioningPlan.Operation.Set.equals(attrReq.getOperation())) {

                                    String setDept = safeGetString(attrReq.getValue());
                                    statement = connection.prepareStatement(
                                        "UPDATE employee SET department = ? WHERE employee_id = ?"
                                    );
                                    statement.setString(1, setDept);
