                                }
                            }
                        }

                        result.setStatus(ProvisioningResult.STATUS_COMMITTED);

                    } else if (AccountRequest.Operation.Disable.equals(op)) {

                        statement = connection.prepareStatement(
                            "UPDATE employee SET status = ? WHERE employee_id = ?"
                        );
                        statement.setInt(1, 0);
                        statement.setString(2, employeeId);
                        statement.executeUpdate();

                        log.info("Disabled employee_id: " + employeeId);
                        result.setStatus(ProvisioningResult.STATUS_COMMITTED);

                    } else if (AccountRequest.Operation.Enable.equals(op)) {

                        statement = connection.prepareStatement(
                            "UPDATE employee SET status = ? WHERE employee_id = ?"
                        );
                        statement.setInt(1, 1);
                        statement.setString(2, employeeId);
                        statement.executeUpdate();

                        log.info("Enabled employee_id: " + employeeId);
                        result.setStatus(ProvisioningResult.STATUS_COMMITTED);

                    } else if (AccountRequest.Operation.Delete.equals(op)) {

                        statement = connection.prepareStatement(
                            "DELETE FROM employee WHERE employee_id = ?"
                        );
                        statement.setString(1, employeeId);
                        statement.executeUpdate();

                        log.info("Deleted employee_id: " + employeeId);
                        result.setStatus(ProvisioningResult.STATUS_COMMITTED);

                    } else {
                        log.warn("Unsupported operation encountered: " + op);
                    }

                } catch (SQLException sqle) {
                    log.error("SQL error while processing operation " + op + " for employee_id " + employeeId, sqle);
                    result.setStatus(ProvisioningResult.STATUS_FAILED);
                    result.addError(sqle);
                } finally {
                    if (statement != null) {
                        try {
                            statement.close();
                        } catch (SQLException closeEx) {
                            log.warn("Failed to close PreparedStatement", closeEx);
                        }
                    }
                }
            }
        }
    }

} catch (Exception e) {
    log.error("Unhandled error in JDBCProvision rule: " + e.getMessage(), e);
    result.setStatus(ProvisioningResult.STATUS_FAILED);
    result.addError(e);
}

log.info("=== Custom JDBCProvision Rule Finished ===");

return result;

