String safeGetString(Object val) {
    if (val == null) return null;
    String strVal = String.valueOf(val).trim();
    return "null".equalsIgnoreCase(strVal) ? null : strVal;
}

String getAttrValue(AccountRequest acctReq, String attrName) {
    if (acctReq == null) return null;
    AttributeRequest attrReq = acctReq.getAttributeRequest(attrName);
    if (attrReq != null) {
        Object val = attrReq.getValue();
        if (val instanceof java.util.List) {
            java.util.List valList = (java.util.List) val;
            if (!valList.isEmpty()) {
                return safeGetString(valList.get(0));
            }
            return null;
        }
        return safeGetString(val);
    }
    return null;
}

// Splits a full name like "John Wick" into [firstname, lastname]
String[] splitName(String fullName) {
    String[] parts = new String[2];
    if (fullName == null) {
        parts[0] = "";
        parts[1] = "";
        return parts;
    }
    String trimmed = fullName.trim();
    int idx = trimmed.indexOf(" ");
    if (idx == -1) {
        parts[0] = trimmed;
        parts[1] = "";
    } else {
        parts[0] = trimmed.substring(0, idx).trim();
        parts[1] = trimmed.substring(idx + 1).trim();
    }
    return parts;
}

