// Step 1: Safely get the existing body
Map body = requestEndPoint.getBody();
if (body == null) {
    body = new HashMap();
}

String jsonBody = (String) body.get("jsonBody");
Map jsonMap;
if (jsonBody == null || jsonBody.trim().isEmpty()) {
    jsonMap = new HashMap();
} else {
    jsonMap = JsonUtil.toMap(jsonBody);
    if (jsonMap == null) {
        jsonMap = new HashMap();
    }
}

// Step 2: Pull each attribute value safely from the provisioning plan
String samAccountName = null;
String userPrincipalName = null;
String firstName = null;
String lastName = null;
String email = null;

if (provisioningPlan != null) {
    for (AccountRequest accReq : Util.iterate(provisioningPlan.getAccountRequests())) {
        for (AttributeRequest attReq : Util.iterate(accReq.getAttributeRequests())) {
            String attrName = attReq.getName();
            Object value = attReq.getValue();
            String strValue = (value != null) ? value.toString() : null;

            if ("samAccountName".equalsIgnoreCase(attrName)) {
                samAccountName = strValue;
            } else if ("userPrincipalName".equalsIgnoreCase(attrName)) {
                userPrincipalName = strValue;
            } else if ("firstName".equalsIgnoreCase(attrName)) {
                firstName = strValue;
            } else if ("lastName".equalsIgnoreCase(attrName)) {
                lastName = strValue;
            } else if ("email".equalsIgnoreCase(attrName)) {
                email = strValue;
            }
        }
    }
}

// Step 3: Apply null-safe defaults (empty string instead of null)
samAccountName = (samAccountName != null) ? samAccountName : "";
userPrincipalName = (userPrincipalName != null) ? userPrincipalName : "";
firstName = (firstName != null) ? firstName : "";
lastName = (lastName != null) ? lastName : "";
email = (email != null) ? email : "";

// username mirrors samAccountName per your Create endpoint's expectation
String username = samAccountName;

// Fixed system-generated password
String password = "TempPass1234";

// Step 4: Build the final safe JSON body
jsonMap.put("username", username);
jsonMap.put("password", password);
jsonMap.put("samAccountName", samAccountName);
jsonMap.put("userPrincipalName", userPrincipalName);
jsonMap.put("firstName", firstName);
jsonMap.put("lastName", lastName);
jsonMap.put("email", email);

String finalBody = JsonUtil.render(jsonMap);
body.put("jsonBody", finalBody);
requestEndPoint.setBody(body);

log.error("BEFORE RULE: Final Create Account body = " + finalBody);

return requestEndPoint;

