String groupValue = null;

if (provisioningPlan != null) {
    for (AccountRequest accReq : Util.iterate(provisioningPlan.getAccountRequests())) {
        log.error("BEFORE RULE: AccountRequest nativeIdentity = " + accReq.getNativeIdentity());
        nativeIdentity = accReq.getNativeIdentity();

        for (AttributeRequest attReq : Util.iterate(accReq.getAttributeRequests())) {
            log.error("BEFORE RULE: AttributeRequest name=" + attReq.getName() + " op=" + attReq.getOp() + " value=" + attReq.getValue());

            // Only treat "memberOf" (your entitlement schema attribute) with op=Remove as the group value
            if ("memberOf".equalsIgnoreCase(attReq.getName())) {
                Object value = attReq.getValue();
                if (value != null) {
                    groupValue = value.toString();
                }
            }
        }
    }
}

log.error("BEFORE RULE: Resolved nativeIdentity = " + nativeIdentity);
log.error("BEFORE RULE: Resolved groupValue = " + groupValue);

// Extract plain username (CN) from the account's full distinguishedName
String username = "";
if (nativeIdentity != null && nativeIdentity.toUpperCase().startsWith("CN=")) {
    int commaIdx = nativeIdentity.indexOf(",");
    username = (commaIdx > -1) ? nativeIdentity.substring(3, commaIdx) : nativeIdentity.substring(3);
} else if (nativeIdentity != null) {
    username = nativeIdentity;
}

// Extract plain groupName (CN) from the group's DN
String groupName = "";
if (groupValue != null && groupValue.toUpperCase().startsWith("CN=")) {
    int commaIdx = groupValue.indexOf(",");
    groupName = (commaIdx > -1) ? groupValue.substring(3, commaIdx) : groupValue.substring(3);
} else if (groupValue != null) {
    groupName = groupValue;
}

jsonMap.put("username", username);
jsonMap.put("groupName", groupName);

String finalBody = JsonUtil.render(jsonMap);
body.put("jsonBody", finalBody);
requestEndPoint.setBody(body);

log.error("BEFORE RULE (Remove Entitlement): Final body = " + finalBody);

return requestEndPoint;

import java.util.HashMap;
import java.util.Map;
import java.util.List;
import java.util.ArrayList;
import connector.common.Util;
import connector.common.JsonUtil;
import sailpoint.connector.webservices.WebServicesClient;

Map updatedMapInfo = new HashMap();
List dataList = new ArrayList();
String samAccountName = null;

if (requestEndPoint != null) {
    Map body = requestEndPoint.getBody();
    if (body != null) {
        String jsonBody = (String) body.get("jsonBody");
        if (jsonBody != null) {
            Map jsonMap = JsonUtil.toMap(jsonBody);
            if (jsonMap != null) {
                samAccountName = (String) jsonMap.get("samAccountName");
            }
        }
    }
}

Map resultMap = new HashMap();
if (samAccountName != null && !samAccountName.trim().isEmpty()) {
    String dn = "CN=" + samAccountName + ",CN=Users,DC=sailpointiiq,DC=local";
    resultMap.put("distinguishedName", dn);
    resultMap.put("samAccountName", samAccountName);

    // Call the Enable endpoint right after Create succeeds, to force userAccountControl=512
    try {
        String enableUrl = "http://192.168.227.1:8080/api/users/enable";

        Map enablePayload = new HashMap();
        enablePayload.put("username", samAccountName);
        String enableJsonBody = JsonUtil.render(enablePayload);

        Map headers = new HashMap();
        headers.put("Content-Type", "application/json");

        List<String> allowedStatuses = new ArrayList();
        allowedStatuses.add("200");
        allowedStatuses.add("2**");

        String enableResponse = restClient.executePut(enableUrl, enableJsonBody, headers, allowedStatuses);
        log.error("AFTER RULE: Enable call response = " + enableResponse);

    } catch (Exception e) {
        log.error("AFTER RULE: Failed to auto-enable account " + samAccountName + " - " + e.getMessage(), e);
    }
}

dataList.add(resultMap);
updatedMapInfo.put("data", dataList);

log.error("AFTER RULE: Constructed data = " + dataList);

return updatedMapInfo;

import connector.common.JsonUtil;
import connector.common.Util;
import java.util.Map;
import java.util.HashMap;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningPlan.AttributeRequest;

Map body = requestEndPoint.getBody();
if (body == null) {
    body = new HashMap();
}

Map jsonMap = new HashMap();

String username = null;
String firstName = null;
String lastName = null;
String email = null;

if (provisioningPlan != null) {
    for (AccountRequest accReq : Util.iterate(provisioningPlan.getAccountRequests())) {

        if (username == null) {
            String accNativeIdentity = accReq.getNativeIdentity();
            if (accNativeIdentity != null && !accNativeIdentity.trim().isEmpty()) {
                username = accNativeIdentity;
            }
        }

        for (AttributeRequest attReq : Util.iterate(accReq.getAttributeRequests())) {
            String attrName = attReq.getName();
            if (attrName != null) {
                attrName = attrName.trim();   // <-- FIX: strip stray whitespace
            }
            Object value = attReq.getValue();
            String strValue = (value != null) ? value.toString() : null;

            log.error("BEFORE RULE (Update Account): AttributeRequest name=" + attrName
                    + " op=" + attReq.getOp() + " value=" + strValue);

            if ("username".equalsIgnoreCase(attrName) || "nativeIdentity".equalsIgnoreCase(attrName)) {
                if (strValue != null && !strValue.trim().isEmpty()) {
                    username = strValue;
                }
            } else if ("firstName".equalsIgnoreCase(attrName)) {
                firstName = strValue;
            } else if ("lastName".equalsIgnoreCase(attrName)) {
                lastName = strValue;
            } else if ("email".equalsIgnoreCase(attrName)) {
                email = strValue;
            }
        }
    }
}

if (username == null || username.trim().isEmpty()) {
    throw new Exception("BEFORE RULE (Update Account): Cannot resolve username - aborting to prevent DN mismatch.");
}

if (username.toUpperCase().startsWith("CN=")) {
    int commaIdx = username.indexOf(",");
    username = (commaIdx > -1) ? username.substring(3, commaIdx) : username.substring(3);
}

jsonMap.put("username", username);
if (firstName != null) jsonMap.put("firstName", firstName);
if (lastName != null) jsonMap.put("lastName", lastName);
if (email != null) jsonMap.put("email", email);

String finalBody = JsonUtil.render(jsonMap);
body.put("jsonBody", finalBody);
requestEndPoint.setBody(body);

log.error("BEFORE RULE (Update Account): Final body = " + finalBody);

return requestEndPoint;

