import sailpoint.object.Identity;

// If NetworkLoginID already has a value, keep it - never recompute after creation
String existing = identity.getAttribute("NetworkLoginID");
if (existing != null && !existing.trim().isEmpty()) {
    return existing;
}

// Only compute a NEW value if none exists yet (first-time / new identity)
String first = identity.getFirstname();
String last = identity.getLastname();

if (first == null || last == null || first.trim().isEmpty() || last.trim().isEmpty()) {
    return null;
}

String generated = (first.substring(0,1) + last).toLowerCase().replaceAll("\\s+", "");
return generated;
